     1→/**
     2→ * Regorus WASM loader and Rego compilation interface.
     3→ *
     4→ * WASM loading strategy:
     5→ * - Synchronous CJS require() via wasm-bindgen nodejs target
     6→ * - Module-level promise for idempotent lazy init (safe for concurrent calls)
     7→ * - Fail-closed: WASM load failure throws; callers catch to return deny
     8→ */
     9→
    10→export type CompileError = {
    11→  line: number;
    12→  column: number;
    13→  message: string;
    14→};
    15→
    16→export type CompileResult =
    17→  | { success: true }
    18→  | { success: false; errors: CompileError[] };
    19→
    20→// ---------------------------------------------------------------------------
    21→// WASM module type (subset of Regorus JS bindings)
    22→// ---------------------------------------------------------------------------
    23→
    24→type RegorusModule = {
    25→  Engine: new () => RegorusEngine;
    26→};
    27→
    28→type RegorusEngine = {
    29→  addPolicy(path: string, rego: string): string;
    30→  free(): void;
    31→};
    32→
    33→// ---------------------------------------------------------------------------
    34→// Module-level idempotent WASM init promise
    35→// Prohibited: module-level mutable singletons (AGENTS.md)
    36→// Allowed: module-level promise is idempotent — concurrent calls share the
    37→// same promise and all await the same result.
    38→// ---------------------------------------------------------------------------
    39→
    40→const regorusModulePromise: Promise<RegorusModule> = (async () => {
    41→  // require() is synchronous; wrapped in promise for uniform async interface
    42→  // eslint-disable-next-line @typescript-eslint/no-require-imports
    43→  const mod = require("../../../../vendor/regorus-wasm/regorusjs") as RegorusModule;
    44→  if (typeof mod.Engine !== "function") {
    45→    throw new Error("Regorus WASM failed to load: Engine class not found");
    46→  }
    47→  return mod;
    48→})();
    49→
    50→// ---------------------------------------------------------------------------
    51→// Error parsing
    52→// ---------------------------------------------------------------------------
    53→
    54→/**
    55→ * Parse the Regorus error string format into structured CompileError objects.
    56→ *
    57→ * Format example:
    58→ *   \n--> test.rego:2:18\n  |\n2 | default allow := !!!\n  |  ^\nerror: invalid character
    59→ *
    60→ * The location header pattern: `--> <file>:<line>:<column>`
    61→ * The error message follows on the last line: `error: <message>`
    62→ */
    63→const parseRegorusErrorString = (errorString: string): CompileError[] => {
    64→  const lines = errorString.split("\n");
    65→  const errors: CompileError[] = [];
    66→
    67→  let currentLine: number | undefined;
    68→  let currentColumn: number | undefined;
    69→
    70→  for (const line of lines) {
    71→    const locationMatch = line.match(/^-->\s+\S+:(\d+):(\d+)\s*$/);
    72→    if (locationMatch) {
    73→      currentLine = parseInt(locationMatch[1], 10);
    74→      currentColumn = parseInt(locationMatch[2], 10);
    75→      continue;
    76→    }
    77→
    78→    const errorMessageMatch = line.match(/^error:\s+(.+)$/);
    79→    if (errorMessageMatch) {
    80→      errors.push({
    81→        line: currentLine ?? 0,
    82→        column: currentColumn ?? 0,
    83→        message: errorMessageMatch[1].trim(),
    84→      });
    85→      currentLine = undefined;
    86→      currentColumn = undefined;
    87→    }
    88→  }
    89→
    90→  if (errors.length === 0 && errorString.trim().length > 0) {
    91→    // Fallback: return the raw error as a single entry without location
    92→    errors.push({ line: 0, column: 0, message: errorString.trim() });
    93→  }
    94→
    95→  return errors;
    96→};
    97→
    98→// ---------------------------------------------------------------------------
    99→// Public API
   100→// ---------------------------------------------------------------------------
   101→
   102→/**
   103→ * Compile a Rego source string using Regorus.
   104→ *
   105→ * Returns { success: true } when the policy parses without errors.
   106→ * Returns { success: false; errors } with structured error locations otherwise.
   107→ *
   108→ * Throws only if the WASM module itself failed to load (fail-closed).
   109→ */
   110→export const compileRego = async (source: string): Promise<CompileResult> => {
   111→  const regorus = await regorusModulePromise;
   112→  const engine = new regorus.Engine();
   113→
   114→  try {
   115→    engine.addPolicy("policy.rego", source);
   116→    return { success: true };
   117→  } catch (err: unknown) {
   118→    const errorString = typeof err === "string" ? err : String(err);
   119→    const errors = parseRegorusErrorString(errorString);
   120→    return { success: false, errors };
   121→  } finally {
   122→    engine.free();
   123→  }
   124→};
   125→

