   105→
   106→export async function createPolicy(
   107→  surreal: Surreal,
   108→  workspaceId: string,
   109→  createdById: string,
   110→  opts: CreatePolicyOptions,
   111→): Promise<{ policyId: string; policyRecord: RecordId<"policy"> }> {
   112→  const policyId = `policy-${crypto.randomUUID()}`;
   113→  const policyRecord = new RecordId("policy", policyId);
   114→  const workspaceRecord = new RecordId("workspace", workspaceId);
   115→  const createdByRecord = new RecordId("identity", createdById);
   116→
   117→  const content: Record<string, unknown> = {
   118→    title: opts.title,
   119→    version: 1,
   120→    status: opts.status ?? "draft",
   121→    selector: opts.selector ?? {},
   122→    rules: opts.rules,
   123→    human_veto_required: opts.human_veto_required ?? false,
   124→    created_by: createdByRecord,
   125→    workspace: workspaceRecord,
   126→    created_at: new Date(),
   127→  };
   128→
   129→  if (opts.description) content.description = opts.description;
   130→  if (opts.max_ttl) content.max_ttl = opts.max_ttl;
   131→
   132→  await surreal.query(`CREATE $policy CONTENT $content;`, {
   133→    policy: policyRecord,
   134→    content,
   135→  });
   136→
   137→  return { policyId, policyRecord };
   138→}
   139→
   140→export async function activatePolicy(
   141→  surreal: Surreal,
   142→  policyId: string,
   143→  creatorId: string,
   144→  workspaceId: string,
   145→): Promise<void> {
   146→  const policyRecord = new RecordId("policy", policyId);
   147→  const creatorRecord = new RecordId("identity", creatorId);
   148→  const workspaceRecord = new RecordId("workspace", workspaceId);
   149→
   150→  await surreal.query(`
   151→    BEGIN TRANSACTION;
   152→      UPDATE $policy SET status = 'active', updated_at = time::now();
   153→      RELATE $creator->governing->$policy SET created_at = time::now();
   154→      RELATE $policy->protects->$workspace SET created_at = time::now();
   155→    COMMIT TRANSACTION;
   156→  `, {
   157→    policy: policyRecord,
   158→    creator: creatorRecord,
   159→    workspace: workspaceRecord,
   160→  });
   161→}
   162→
   163→export async function deprecatePolicy(
   164→  surreal: Surreal,
   165→  policyId: string,
   166→): Promise<void> {
   167→  const policyRecord = new RecordId("policy", policyId);
   168→
   169→  await surreal.query(`
   170→    BEGIN TRANSACTION;
   171→      UPDATE $policy SET status = 'deprecated', updated_at = time::now();
   172→      DELETE governing WHERE out = $policy;
   173→      DELETE protects WHERE in = $policy;
   174→    COMMIT TRANSACTION;
   175→  `, { policy: policyRecord });
   176→}
