   129→async function handleListPolicies(
   130→  deps: ServerDependencies,
   131→  workspaceId: string,
   132→  request: Request,
   133→): Promise<Response> {
   134→  const identityOrError = await resolveIdentityFromSession(deps, request);
   135→  if (isResponse(identityOrError)) return identityOrError;
   136→
   137→  const workspaceOrError = await resolveWorkspace(deps, workspaceId, "policy.list.workspace_resolve.failed");
   138→  if (isResponse(workspaceOrError)) return workspaceOrError;
   139→  const workspaceRecord = workspaceOrError;
   140→
   141→  try {
   142→    const url = new URL(request.url);
   143→    const VALID_STATUSES: ReadonlySet<string> = new Set(["draft", "testing", "active", "deprecated", "superseded"]);
   144→    const rawStatus = url.searchParams.get("status");
   145→    const statusFilter = rawStatus && VALID_STATUSES.has(rawStatus)
   146→      ? (rawStatus as PolicyStatus)
   147→      : undefined;
   148→
   149→    const policies = await listWorkspacePolicies(
   150→      deps.surreal,
   151→      workspaceRecord,
   152→      statusFilter || undefined,
   153→    );
   154→
   155→    return jsonResponse({ policies }, 200);
   156→  } catch (error) {
   157→    log.error("policy.list.failed", "Failed to list policies", error, { workspaceId });
   158→    return jsonError("failed to list policies", 500);
   159→  }
   160→}
