   226→  const workspaceOrError = await resolveWorkspace(deps, workspaceId, "policy.create.workspace_resolve.failed");
   227→  if (isResponse(workspaceOrError)) return workspaceOrError;
   228→  const workspaceRecord = workspaceOrError;
   229→
   230→  let body: unknown;
   231→  try {
   232→    body = await request.json();
   233→  } catch {
   234→    return jsonError("invalid JSON body", 400);
   235→  }
   236→
   237→  const validation = validatePolicyCreateBody(body as { title: unknown; description: unknown; rego_source: unknown });
   238→  if (!validation.valid) {
   239→    return jsonError(validation.errors[0], 400);
