   259→    return jsonError("failed to create policy", 500);
   260→  }
   261→}
   262→
   263→// ---------------------------------------------------------------------------
   264→// PATCH /api/workspaces/:workspaceId/policies/:policyId/activate (stub - guarded)
   265→// ---------------------------------------------------------------------------
   266→
   267→/** Statuses from which activation is allowed. */
   268→const ACTIVATABLE_STATUSES: ReadonlySet<PolicyStatus> = new Set<PolicyStatus>(["draft", "testing"]);
   269→
   270→async function handleActivatePolicy(
   271→  deps: ServerDependencies,
   272→  workspaceId: string,
   273→  policyId: string,
   274→  request: Request,
   275→): Promise<Response> {
   276→  const guardResult = await requireHumanIdentity(deps, request);
   277→  if (isResponse(guardResult)) return guardResult;
   278→
   279→  const workspaceOrError = await resolveWorkspace(deps, workspaceId, "policy.activate.workspace_resolve.failed");
   280→  if (isResponse(workspaceOrError)) return workspaceOrError;
   281→  const workspaceRecord = workspaceOrError;
   282→
   283→  try {
   284→    const policyRecord = new RecordId("policy", policyId);
   285→    const policy = await deps.surreal.select<PolicyRecord>(policyRecord);
   286→
   287→    if (!policy || (policy.workspace.id as string) !== (workspaceRecord.id as string)) {
   288→      return jsonError("policy not found", 404);
   289→    }
   290→
   291→    if (!ACTIVATABLE_STATUSES.has(policy.status)) {
   292→      return jsonError(
   293→        `policy must be in draft or testing status to activate (current: ${policy.status})`,
   294→        409,
   295→      );
   296→    }
   297→
   298→    await activatePolicy(
   299→      deps.surreal,
   300→      policy,
   301→      guardResult.identityRecord,
   302→      workspaceRecord,
