   309→  }
   310→}
   311→
   312→// ---------------------------------------------------------------------------
   313→// PATCH /api/workspaces/:workspaceId/policies/:policyId/deprecate (stub - guarded)
   314→// ---------------------------------------------------------------------------
   315→
   316→/** Only active policies can be deprecated. */
   317→const DEPRECATABLE_STATUSES: ReadonlySet<PolicyStatus> = new Set<PolicyStatus>(["active"]);
   318→
   319→async function handleDeprecatePolicy(
   320→  deps: ServerDependencies,
   321→  workspaceId: string,
   322→  policyId: string,
   323→  request: Request,
   324→): Promise<Response> {
   325→  const guardResult = await requireHumanIdentity(deps, request);
   326→  if (isResponse(guardResult)) return guardResult;
   327→
   328→  const workspaceOrError = await resolveWorkspace(deps, workspaceId, "policy.deprecate.workspace_resolve.failed");
   329→  if (isResponse(workspaceOrError)) return workspaceOrError;
   330→  const workspaceRecord = workspaceOrError;
   331→
   332→  try {
   333→    const policyRecord = new RecordId("policy", policyId);
   334→    const policy = await deps.surreal.select<PolicyRecord>(policyRecord);
   335→
   336→    if (!policy || (policy.workspace.id as string) !== (workspaceRecord.id as string)) {
   337→      return jsonError("policy not found", 404);
   338→    }
   339→
   340→    if (!DEPRECATABLE_STATUSES.has(policy.status)) {
   341→      return jsonError(
   342→        `policy must be in active status to deprecate (current: ${policy.status})`,
   343→        409,
   344→      );
   345→    }
   346→
   347→    await deprecatePolicy(deps.surreal, policyId);
   348→
   349→    return jsonResponse({ status: "deprecated" }, 200);
   350→  } catch (error) {
   351→    log.error("policy.deprecate.failed", "Failed to deprecate policy", error, { workspaceId, policyId });
   352→    return jsonError("failed to deprecate policy", 500);
   353→  }
   354→}
   355→
   356→// ---------------------------------------------------------------------------
   357→// POST /api/workspaces/:workspaceId/policies/:policyId/versions (stub - guarded)
   358→// ---------------------------------------------------------------------------
   359→
   360→/** Only active policies can spawn new versions. */
   361→const VERSIONABLE_STATUSES: ReadonlySet<PolicyStatus> = new Set<PolicyStatus>(["active"]);
   362→
   363→async function handleCreatePolicyVersion(
   364→  deps: ServerDependencies,
   365→  workspaceId: string,
   366→  policyId: string,
   367→  request: Request,
   368→): Promise<Response> {
   369→  const guardResult = await requireHumanIdentity(deps, request);
   370→  if (isResponse(guardResult)) return guardResult;
   371→
   372→  const workspaceOrError = await resolveWorkspace(deps, workspaceId, "policy.version.workspace_resolve.failed");
   373→  if (isResponse(workspaceOrError)) return workspaceOrError;
   374→  const workspaceRecord = workspaceOrError;
   375→
   376→  try {
   377→    const sourcePolicy = await getPolicyById(deps.surreal, policyId, workspaceRecord);
   378→    if (!sourcePolicy) {
   379→      return jsonError("policy not found", 404);
   380→    }
   381→
   382→    if (!VERSIONABLE_STATUSES.has(sourcePolicy.status)) {
   383→      return jsonError(
   384→        `policy must be in active status to create a new version (current: ${sourcePolicy.status})`,
   385→        409,
   386→      );
   387→    }
   388→
   389→    // Parse optional overrides from request body — callers can customise the
   390→    // new draft instead of getting an exact copy of the source policy.
   391→    let overrides: Partial<{
   392→      title: string;
   393→      description: string;
   394→      selector: PolicySelector;
   395→      rego_source: string;
   396→      human_veto_required: boolean;
   397→      max_ttl: string;
   398→    }> = {};
   399→    try {
   400→      const raw = await request.json();
   401→      if (raw && typeof raw === "object") overrides = raw as typeof overrides;
   402→    } catch {
   403→      // No body or invalid JSON — use source values only.
   404→    }
   405→
   406→    // When overrides include rego_source, validate through the same path as create.
   407→    if (overrides.rego_source !== undefined) {
   408→      const validation = validatePolicyCreateBody({
   409→        title: overrides.title ?? sourcePolicy.title,
   410→        description: overrides.description ?? sourcePolicy.description ?? "",
   411→        rego_source: overrides.rego_source,
   412→      });
   413→      if (!validation.valid) {
   414→        return jsonError(validation.errors[0], 400);
   415→      }
   416→    }
   417→
   418→    const sourcePolicyRecord = new RecordId("policy", policyId);
   419→    const { policyId: newPolicyId, version } = await createPolicy(deps.surreal, {
   420→      title: overrides.title ?? sourcePolicy.title,
   421→      description: overrides.description ?? sourcePolicy.description,
   422→      selector: overrides.selector ?? sourcePolicy.selector,
   423→      rego_source: overrides.rego_source ?? sourcePolicy.rego_source,
   424→      human_veto_required: overrides.human_veto_required ?? sourcePolicy.human_veto_required,
   425→      max_ttl: overrides.max_ttl ?? sourcePolicy.max_ttl,
   426→      createdBy: guardResult.identityRecord,
   427→      workspace: workspaceRecord,
   428→      supersedes: sourcePolicyRecord,
   429→    });
   430→
   431→    return jsonResponse({ policy_id: newPolicyId, version }, 201);
   432→  } catch (error) {
   433→    log.error("policy.version.failed", "Failed to create policy version", error, { workspaceId, policyId });
   434→    return jsonError("failed to create policy version", 500);
   435→  }
   436→}
   437→
   438→// ---------------------------------------------------------------------------
   439→// GET /api/workspaces/:workspaceId/policies/:policyId/versions
   440→// ---------------------------------------------------------------------------
   441→
   442→async function handleGetVersionHistory(
   443→  deps: ServerDependencies,
   444→  workspaceId: string,
   445→  policyId: string,
   446→  request: Request,
   447→): Promise<Response> {
