   451→  const workspaceOrError = await resolveWorkspace(deps, workspaceId, "policy.versions.workspace_resolve.failed");
   452→  if (isResponse(workspaceOrError)) return workspaceOrError;
   453→  const workspaceRecord = workspaceOrError;
