   147→export async function deprecatePolicy(
   148→  surreal: Surreal,
   149→  policyId: string,
   150→): Promise<void> {
   151→  const policyRecord = new RecordId("policy", policyId);
   152→
   153→  await surreal.query(`
   154→    BEGIN TRANSACTION;
   155→      UPDATE $policy SET status = 'deprecated', updated_at = time::now();
   156→      DELETE governing WHERE out = $policy;
   157→      DELETE protects WHERE in = $policy;
   158→    COMMIT TRANSACTION;
   159→  `, { policy: policyRecord });
   160→}
