   211→export async function simulatePolicyGateResult(
   212→  surreal: Surreal,
   213→  intentId: string,
   214→  result: {
   215→    decision: "APPROVE" | "REJECT";
   216→    risk_score: number;
   217→    reason: string;
   218→    policy_only: boolean;
   219→    policy_trace: PolicyTraceEntry[];
   220→    human_veto_required?: boolean;
   221→  },
   222→  resultStatus: "authorized" | "pending_veto" | "vetoed",
   223→): Promise<void> {
   224→  const intentRecord = new RecordId("intent", intentId);
   225→  const evalContent: Record<string, unknown> = {
   226→    decision: result.decision,
   227→    risk_score: result.risk_score,
   228→    reason: result.reason,
   229→    evaluated_at: new Date(),
   230→    policy_only: result.policy_only,
   231→    policy_trace: result.policy_trace,
   232→  };
   233→  if (result.human_veto_required !== undefined) {
   234→    evalContent.human_veto_required = result.human_veto_required;
   235→  }
   236→
   237→  const updates: Record<string, unknown> = {
   238→    status: resultStatus,
   239→    evaluation: evalContent,
   240→    updated_at: new Date(),
   241→  };
   242→
   243→  if (resultStatus === "pending_veto") {
   244→    updates.veto_expires_at = new Date(Date.now() + 5 * 60 * 1000);
   245→  }
   246→
   247→  await surreal.query(`UPDATE $intent MERGE $updates;`, {
   248→    intent: intentRecord,
   249→    updates,
   250→  });
   251→}
