   295→export async function createPolicyVersion(
   296→  surreal: Surreal,
   297→  oldPolicyId: string,
   298→  workspaceId: string,
   299→  createdById: string,
   300→  newRegoSource: string,
   301→): Promise<{ policyId: string }> {
   302→  const oldPolicy = await getPolicyRecord(surreal, oldPolicyId);
   303→  const newPolicyId = `policy-${crypto.randomUUID()}`;
   304→  const newPolicyRecord = new RecordId("policy", newPolicyId);
   305→  const oldPolicyRecord = new RecordId("policy", oldPolicyId);
   306→  const workspaceRecord = new RecordId("workspace", workspaceId);
   307→  const createdByRecord = new RecordId("identity", createdById);
   308→
   309→  await surreal.query(`
   310→    BEGIN TRANSACTION;
   311→      CREATE $newPolicy CONTENT {
   312→        title: $title,
   313→        version: $newVersion,
   314→        status: 'active',
   315→        selector: $selector,
   316→        rego_source: $regoSource,
   317→        human_veto_required: $vetoRequired,
   318→        created_by: $createdBy,
   319→        workspace: $workspace,
   320→        supersedes: $oldPolicy,
   321→        created_at: time::now()
   322→      };
   323→      UPDATE $oldPolicy SET status = 'superseded', updated_at = time::now();
   324→    COMMIT TRANSACTION;
   325→  `, {
   326→    newPolicy: newPolicyRecord,
   327→    oldPolicy: oldPolicyRecord,
   328→    title: oldPolicy.title,
   329→    newVersion: (oldPolicy.version as number) + 1,
   330→    selector: oldPolicy.selector,
   331→    regoSource: newRegoSource,
   332→    vetoRequired: oldPolicy.human_veto_required,
   333→    createdBy: createdByRecord,
   334→    workspace: workspaceRecord,
   335→  });
   336→
   337→  return { policyId: newPolicyId };
   338→}
