    reason: string;
    policy_only: boolean;
    policy_trace: PolicyTraceEntry[];
    human_veto_required?: boolean;
    evidence_requirement?: {
      min_count: number;
      required_types: string[];
    };
  },
  resultStatus: "authorized" | "pending_veto" | "vetoed",
